    @Override
    public void setupAnim(T entity, float limbSwing, float limbSwingAmount,
                          float ageInTicks, float netHeadYaw, float headPitch) {
        this.head.yRot = netHeadYaw * ((float) Math.PI / 180F);
        this.head.xRot = headPitch * ((float) Math.PI / 180F) + 0.10F;
        float amount = Math.min(limbSwingAmount, 1.0F);
        float cycle = limbSwing * 0.6662F * 0.90F;
        float stride = (float) Math.cos(cycle) * 0.00F * amount;
        boolean hunting = entity != null && entity.getTarget() != null;
        this.armLeft.xRot = (hunting ? -1.4F : 0.0F) + (float) Math.sin(ageInTicks * 0.08F) * 0.08F;
        this.armRight.xRot = (hunting ? -1.4F : 0.0F) + -(float) Math.sin(ageInTicks * 0.08F) * 0.08F;
        this.root.y = (float) Math.sin(ageInTicks * 0.12F) * 1.20F;
        this.tendril00.xRot = (float) Math.sin(ageInTicks * 0.07F + 0.00F) * 0.18F;
        this.tendril10.xRot = (float) Math.sin(ageInTicks * 0.07F + 1.30F) * 0.18F;
        this.tendril20.xRot = (float) Math.sin(ageInTicks * 0.07F + 2.60F) * 0.18F;
        this.tendril30.xRot = (float) Math.sin(ageInTicks * 0.07F + 3.90F) * 0.18F;
        this.tendril40.xRot = (float) Math.sin(ageInTicks * 0.07F + 5.20F) * 0.18F;
        this.root.zRot = (float) Math.sin(cycle) * 0.03F * amount;
    }

    @Override
    public void renderToBuffer(PoseStack pose, VertexConsumer buffer, int light,
                               int overlay, int colour) {
        this.root.render(pose, buffer, light, overlay, colour);
    }
